import ast, os, re, sys

def reconstruct(diff_path):
    files = {}
    cur = None
    lines = open(diff_path).read().split('\n')
    i = 0
    while i < len(lines):
        line = lines[i]
        if line.startswith('diff --git '):
            m = re.match(r'diff --git a/(\S+) b/(\S+)', line)
            cur = m.group(2)
            files.setdefault(cur, [])
        elif line.startswith('+') and not line.startswith('+++') and cur:
            files[cur].append(line[1:])
        i += 1
    return {k: '\n'.join(v) for k, v in files.items()}

def api(src):
    try:
        tree = ast.parse(src)
    except SyntaxError as e:
        return None, str(e)
    out = {}
    for node in tree.body:
        if isinstance(node, (ast.ClassDef,)):
            methods = set()
            for b in node.body:
                if isinstance(b, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    methods.add(b.name)
                elif isinstance(b, ast.AnnAssign) and isinstance(b.target, ast.Name):
                    methods.add('@'+b.target.id)
                elif isinstance(b, ast.Assign):
                    for t in b.targets:
                        if isinstance(t, ast.Name):
                            methods.add('@'+t.id)
            out['class '+node.name] = methods
        elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            out['def '+node.name] = set()
        elif isinstance(node, ast.Assign):
            for t in node.targets:
                if isinstance(t, ast.Name):
                    out['var '+t.id] = set()
    return out, None

for which in ['circt']:
    gold = reconstruct(f'gold_patches/{which}.diff')
    for path, src in gold.items():
        if not path.startswith('src/'): continue
