"""SV dialect: SystemVerilog constructs and textual emission."""
from __future__ import annotations
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional


@dataclass
class SVWireOp:
    """`sv.wire` declaration."""
    name: str
    width: int = 1
    initial_value: Optional[int] = None

    def emit(self) -> str:
        if self.width == 1:
            return f"  wire {self.name};"
        return f"  wire [{self.width - 1}:0] {self.name};"


@dataclass
class SVRegOp:
    """`sv.reg` declaration."""
    name: str
    width: int = 1
    initial_value: Optional[int] = None

    def emit(self) -> str:
        if self.width == 1:
            return f"  reg {self.name};"
        return f"  reg [{self.width - 1}:0] {self.name};"


@dataclass
class AssignOp:
    """`sv.assign`: continuous assignment."""
    target: str
    expression: str

    def emit(self) -> str:
        return f"  assign {self.target} = {self.expression};"


@dataclass
class IfOp:
    """`sv.if`: procedural conditional."""
    condition: str
    then_body: List[str] = field(default_factory=list)
    else_body: List[str] = field(default_factory=list)

    def emit(self, indent: int = 4) -> str:
        pad = " " * indent
        lines = [f"{pad}if ({self.condition}) begin"]
        for stmt in self.then_body:
            lines.append(f"{pad}  {stmt}")
        if self.else_body:
            lines.append(f"{pad}end else begin")
            for stmt in self.else_body:
                lines.append(f"{pad}  {stmt}")
        lines.append(f"{pad}end")
        return "\n".join(lines)


@dataclass
class AlwaysCombOp:
    """`sv.alwayscomb` block."""
    body: List[str] = field(default_factory=list)

    def emit(self) -> str:
        lines = ["  always_comb begin"]
        for stmt in self.body:
            lines.append(f"    {stmt}")
        lines.append("  end")
        return "\n".join(lines)


@dataclass
class AlwaysFFOp:
    """`sv.alwaysff` block with clock and optional reset."""
    clock: str = "clk"
    reset: Optional[str] = None
