"""Kernel-level IR: the acceleration-oriented view of a design.

A :class:`KernelOp` is a flat list of operations with symbolic operands and
results -- the shape HLS front ends produce before scheduling. The rest of this
module supplies the pieces scheduling needs: a latency model, resource binding,
pipeline structure, array partitioning and streaming interfaces.

Latencies live in :class:`LatencyModel` rather than on the operations, so the
same kernel can be re-costed for a different technology by swapping the model.
"""
from __future__ import annotations
from dataclasses import dataclass, field
from enum import Enum
from typing import Any, Dict, List, Optional, Set, Tuple


class ScheduleConstraint(Enum):
    """How an operation may be placed in time."""
    ASAP = "as_soon_as_possible"
    ALAP = "as_late_as_possible"
    FIXED = "fixed_cycle"
    RELATIVE = "relative_offset"


class ResourceType(Enum):
    """Physical resources an operation can be bound to."""
    ALU = "alu"
    MULTIPLIER = "multiplier"
    MEMORY_PORT = "memory_port"
    DSP = "dsp"
    BRAM = "bram"
    REGISTER = "register"


#: Cycle cost of each operation kind, used when a kernel does not override it.
DEFAULT_LATENCIES: Dict[str, int] = {
    "add": 1, "sub": 1, "mul": 3, "div": 10,
    "load": 2, "store": 1, "cmp": 1, "mux": 0,
    "shift": 1, "and": 1, "or": 1, "xor": 1,
}

#: Default number of instances available per resource kind.
DEFAULT_RESOURCE_LIMITS: Dict[ResourceType, int] = {
    ResourceType.ALU: 4,
    ResourceType.MULTIPLIER: 2,
    ResourceType.MEMORY_PORT: 2,
    ResourceType.DSP: 8,
    ResourceType.BRAM: 4,
}


@dataclass
class LatencyModel:
    """Cycle cost of each operation kind."""
    operation_latencies: Dict[str, int] = field(default_factory=dict)
    default_latency: int = 1

    def __post_init__(self) -> None:
        if not self.operation_latencies:
            self.operation_latencies = dict(DEFAULT_LATENCIES)

    def get_latency(self, op_type: str) -> int:
        return self.operation_latencies.get(op_type, self.default_latency)

    def set_latency(self, op_type: str, cycles: int) -> None:
        self.operation_latencies[op_type] = cycles

    def total_latency(self, op_types: List[str]) -> int:
        return sum(self.get_latency(op) for op in op_types)


@dataclass
class ResourceBinding:
    """Assignment of operations to numbered resource instances."""
    bindings: Dict[str, Tuple[ResourceType, int]] = field(default_factory=dict)
    resource_limits: Dict[ResourceType, int] = field(default_factory=dict)

    def __post_init__(self) -> None:
        if not self.resource_limits:
            self.resource_limits = dict(DEFAULT_RESOURCE_LIMITS)

    def bind(self, op_name: str, resource: ResourceType, instance: int) -> bool:
        """Bind `op_name`; ``False`` when `instance` is outside the budget."""
        limit = self.resource_limits.get(resource, 1)
        if instance >= limit:
            return False
        self.bindings[op_name] = (resource, instance)
        return True

    def get_binding(self, op_name: str) -> Optional[Tuple[ResourceType, int]]:
        return self.bindings.get(op_name)

    def utilization(self, resource: ResourceType) -> float:
        bound = sum(1 for kind, _ in self.bindings.values() if kind == resource)
        limit = self.resource_limits.get(resource, 1)
        return bound / limit if limit > 0 else 0.0

    def is_available(self, resource: ResourceType, instance: int) -> bool:
        for kind, index in self.bindings.values():
            if kind == resource and index == instance:
                return False
        return instance < self.resource_limits.get(resource, 1)


@dataclass
class KernelOp:
    """A kernel: operations plus the models used to schedule them."""
    name: str
    operations: List[Dict[str, Any]] = field(default_factory=list)
    inputs: List[Dict[str, Any]] = field(default_factory=list)
    outputs: List[Dict[str, Any]] = field(default_factory=list)
    latency_model: LatencyModel = field(default_factory=LatencyModel)
    resource_binding: ResourceBinding = field(default_factory=ResourceBinding)
    schedule: Dict[str, int] = field(default_factory=dict)

    def add_operation(self, name: str, op_type: str, operands: List[str],
                      result: str) -> None:
        self.operations.append({
            "name": name, "op_type": op_type,
            "operands": operands, "result": result,
        })

    def add_input(self, name: str, width: int = 32) -> None:
        self.inputs.append({"name": name, "width": width})

    def add_output(self, name: str, width: int = 32) -> None:
        self.outputs.append({"name": name, "width": width})

    def get_operation(self, name: str) -> Optional[Dict[str, Any]]:
        for op in self.operations:
            if op["name"] == name:
                return op
        return None

    def total_operations(self) -> int:
        return len(self.operations)

    def critical_path_latency(self) -> int:
        """Summed latency of every operation, i.e. the unpipelined cost."""
        if not self.operations:
            return 0
        return sum(self.latency_model.get_latency(op["op_type"])
                   for op in self.operations)

    def estimated_cycles(self) -> int:
        """Length of the current schedule, or the critical path if unscheduled."""
        if self.schedule:
            return max(self.schedule.values()) + 1
        return self.critical_path_latency()

    def defined_values(self) -> Set[str]:
        """Every SSA-like name this kernel produces."""
        return {op["result"] for op in self.operations if op["result"]}

    def free_values(self) -> Set[str]:
        """Operands that no operation in the kernel defines."""
        defined = self.defined_values() | {inp["name"] for inp in self.inputs}
        used: Set[str] = set()
        for op in self.operations:
            used.update(op["operands"])
        return used - defined

    def operation_types(self) -> List[str]:
        return [op["op_type"] for op in self.operations]

    def __len__(self) -> int:
        return len(self.operations)


@dataclass
class DataflowOp:
    """An operation that fires once all of its input tokens are available."""
    name: str
    op_type: str
    input_tokens: List[str] = field(default_factory=list)
    output_tokens: List[str] = field(default_factory=list)
    latency: int = 1
    is_ready: bool = False

    def check_ready(self, available_tokens: set) -> bool:
        self.is_ready = all(token in available_tokens
                            for token in self.input_tokens)
        return self.is_ready

    def fire(self) -> List[str]:
        if not self.is_ready:
            return []
        self.is_ready = False
        return list(self.output_tokens)

    def token_count(self) -> int:
        return len(self.input_tokens) + len(self.output_tokens)


@dataclass
class PipelineOp:
    """A pipeline: `stages` stages accepting work every `initiation_interval`."""
    name: str
    stages: int = 1
    initiation_interval: int = 1
    operations_per_stage: List[List[str]] = field(default_factory=list)
    is_active: bool = False
    current_stage: int = 0

    def __post_init__(self) -> None:
        if not self.operations_per_stage:
            self.operations_per_stage = [[] for _ in range(self.stages)]

    def assign_to_stage(self, op_name: str, stage: int) -> bool:
        if 0 <= stage < self.stages:
            self.operations_per_stage[stage].append(op_name)
            return True
        return False

    def advance(self) -> int:
        self.current_stage = (self.current_stage + 1) % self.stages
        return self.current_stage

    def throughput(self) -> float:
        """Results per cycle once the pipeline is full."""
        if self.initiation_interval == 0:
            return 0.0
        return 1.0 / self.initiation_interval

    def pipeline_depth(self) -> int:
        return self.stages

    def stage_operations(self, stage: int) -> List[str]:
        if 0 <= stage < self.stages:
            return self.operations_per_stage[stage]
        return []

    def fill_latency(self) -> int:
        """Cycles before the first result leaves the pipeline."""
        return self.stages * self.initiation_interval


@dataclass
class ArrayPartitionOp:
    """Array partitioning, which is what makes parallel access possible."""
    name: str
    array_size: int
    partition_type: str = "cyclic"
    factor: int = 2
    dimension: int = 0

    def num_partitions(self) -> int:
        if self.partition_type == "complete":
            return self.array_size
        return min(self.factor, self.array_size)

    def partition_index(self, array_index: int) -> int:
        """Which partition `array_index` lands in."""
        if self.partition_type == "cyclic":
            return array_index % self.factor
        if self.partition_type == "block":
            block_size = self.array_size // self.factor
            if block_size <= 0:
                return 0
            return min(array_index // block_size, self.factor - 1)
        if self.partition_type == "complete":
            return array_index
        return 0

    def local_index(self, array_index: int) -> int:
        """Offset of `array_index` inside its partition."""
        if self.partition_type == "cyclic":
            return array_index // self.factor
        if self.partition_type == "block":
            block_size = self.array_size // self.factor
            return array_index % block_size if block_size > 0 else 0
        return array_index

    def max_parallel_accesses(self) -> int:
        return self.num_partitions()


@dataclass
class StreamOp:
    """A bounded stream, the data-movement primitive between kernels."""
    name: str
    data_width: int = 32
    depth: int = 16
    direction: str = "in"
    buffer: List[int] = field(default_factory=list)
    read_count: int = 0
    write_count: int = 0

    def write(self, value: int) -> bool:
        if len(self.buffer) >= self.depth:
            return False
        self.buffer.append(value & ((1 << self.data_width) - 1))
        self.write_count += 1
        return True

    def read(self) -> Optional[int]:
        if not self.buffer:
            return None
        self.read_count += 1
        return self.buffer.pop(0)

    def is_empty(self) -> bool:
        return len(self.buffer) == 0

    def is_full(self) -> bool:
        return len(self.buffer) >= self.depth

    def occupancy(self) -> int:
        return len(self.buffer)

    def bandwidth_utilization(self) -> float:
        """How balanced reads and writes are; 1.0 means perfectly matched."""
        total = self.read_count + self.write_count
        if total == 0:
            return 0.0
        return min(self.read_count, self.write_count) / max(self.read_count,
                                                           self.write_count)

