        self.schedule: Dict[str, int] = {}
        self.resource_limits: Dict[str, int] = {"alu": 4, "mul": 2, "mem": 2}
        self.latency_table: Dict[str, int] = dict(LATENCY_TABLE)

    # -- graph construction ----------------------------------------------

    def add_node(self, name: str, op_type: str,
                 predecessors: Optional[List[str]] = None) -> None:
        node = ScheduleNode(
            name=name, op_type=op_type,
            latency=self.latency_table.get(op_type, 1),
            resource_type=resource_class_of(op_type),
            predecessors=list(predecessors or []),
        )
        self.nodes[name] = node
        for pred in node.predecessors:
            if pred in self.nodes:
                self.nodes[pred].successors.append(name)

    def latencies(self) -> Dict[str, int]:
        return {name: node.latency for name, node in self.nodes.items()}

    # -- scheduling ------------------------------------------------------

    def schedule_asap(self) -> Dict[str, int]:
        """Each operation at the first cycle its predecessors permit."""
        self.schedule = {}
        for name in self._topological_sort():
            node = self.nodes[name]
            start = node.earliest_start(self.schedule, self.latencies())
            self.schedule[name] = start
            node.scheduled_cycle = start
        return dict(self.schedule)

    def schedule_alap(self, deadline: int) -> Dict[str, int]:
        """Each operation as late as `deadline` allows."""
        self.schedule = {}
        for name in reversed(self._topological_sort()):
            node = self.nodes[name]
            if not node.successors:
                end_time = deadline - node.latency
            else:
                end_time = min(self.schedule.get(s, deadline)
                               for s in node.successors) - node.latency
            self.schedule[name] = max(0, end_time)
            node.scheduled_cycle = self.schedule[name]
        return dict(self.schedule)

    def slack(self, deadline: int) -> Dict[str, int]:
        """ALAP minus ASAP placement: how movable each operation is."""
        asap = self.schedule_asap()
        alap = self.schedule_alap(deadline)
        self.schedule = asap
        for name, cycle in asap.items():
            self.nodes[name].scheduled_cycle = cycle
        return {name: alap[name] - asap[name] for name in asap}

    def schedule_list(self) -> Dict[str, int]:
        """Greedy list scheduling: never exceed the per-cycle resource limits."""
        self.schedule = {}
        ready = [name for name, node in self.nodes.items()
                 if not node.predecessors]
        scheduled: Set[str] = set()
        cycle = 0
        # Every cycle either schedules something or advances time, so the loop
        # cannot run longer than one cycle per node plus their latencies.
        budget = max(1, len(self.nodes)) * 20
        while len(scheduled) < len(self.nodes) and budget > 0:
            budget -= 1
            usage: Dict[str, int] = {}
            # Prefer operations that unblock the most work.
            ready.sort(key=lambda n: len(self.nodes[n].successors), reverse=True)
            placed_now: List[str] = []
            for name in list(ready):
                node = self.nodes[name]
                used = usage.get(node.resource_type, 0)
                if used < self.resource_limits.get(node.resource_type, 4):
                    self.schedule[name] = cycle
                    node.scheduled_cycle = cycle
                    usage[node.resource_type] = used + 1
                    placed_now.append(name)
                    scheduled.add(name)
            for name in placed_now:
                ready.remove(name)
            cycle += 1
            for name, node in self.nodes.items():
                if name in scheduled or name in ready:
                    continue
                if all(pred in scheduled
                       and self.schedule[pred] + self.nodes[pred].latency <= cycle
                       for pred in node.predecessors):
                    ready.append(name)
        return dict(self.schedule)

    # -- schedule metrics ------------------------------------------------

    def compute_initiation_interval(self) -> int:
        """Smallest II the current schedule's resource pressure allows."""
        if not self.schedule:
            return 1
        per_cycle: Dict[int, Dict[str, int]] = {}
        for name, cycle in self.schedule.items():
            node = self.nodes[name]
            for busy in range(cycle, cycle + node.latency):
                usage = per_cycle.setdefault(busy, {})
                usage[node.resource_type] = usage.get(node.resource_type, 0) + 1
        interval = 1
        for usage in per_cycle.values():
            for resource, count in usage.items():
                limit = self.resource_limits.get(resource, 4)
                interval = max(interval, -(-count // limit))
        return interval

    def total_schedule_length(self) -> int:
        """Cycle at which the last operation completes."""
        if not self.schedule:
            return 0
        return max(cycle + self.nodes[name].latency
                   for name, cycle in self.schedule.items())

    def build_pipeline_stages(self) -> List[PipelineStage]:
        """One :class:`PipelineStage` per cycle of the current schedule."""
        if not self.schedule:
            return []
        num_stages = self.total_schedule_length()
        stages = [PipelineStage(stage_id=i) for i in range(num_stages)]
        for name, cycle in self.schedule.items():
            node = self.nodes[name]
            if 0 <= cycle < num_stages:
                stages[cycle].add_operation(name, node.resource_type)
        return stages

    def resource_usage_at(self, cycle: int) -> Dict[str, int]:
        usage: Dict[str, int] = {}
        for name, start in self.schedule.items():
            node = self.nodes[name]
            if start <= cycle < start + node.latency:
                usage[node.resource_type] = usage.get(node.resource_type, 0) + 1
        return usage

