        """Dependence violations in the current schedule."""
        errors: List[str] = []
        for name, cycle in self.schedule.items():
            for pred in self.nodes[name].predecessors:
                if pred not in self.schedule:
                    errors.append(f"{name} depends on unscheduled {pred}")
                    continue
                ready = self.schedule[pred] + self.nodes[pred].latency
                if cycle < ready:
                    errors.append(
                        f"{name} starts at {cycle} but {pred} finishes at {ready}")
        return errors

    def _topological_sort(self) -> List[str]:
        visited: Set[str] = set()
        order: List[str] = []

        def visit(name: str) -> None:
