        self.nodes[name] = ScheduleNode(
            name=name, op_type=op_type, latency=latency,
            resource_type=resource_class_of(op_type),
            predecessors=list(predecessors or []),
        )

    def schedule_modulo(self) -> Dict[str, Tuple[int, int]]:
        """Place each operation ASAP, then split the cycle into slot and stage."""
        self.schedule = {}
        for name in self._topological_sort():
            node = self.nodes[name]
            earliest = 0
            for pred in node.predecessors:
                if pred in self.schedule:
                    pred_cycle, _ = self.schedule[pred]
                    earliest = max(earliest,
                                   pred_cycle + self.nodes[pred].latency)
            self.schedule[name] = (earliest, earliest // self.ii)
            node.scheduled_cycle = earliest
        return dict(self.schedule)

    def stage_of(self, name: str) -> int:
        return self.schedule[name][1] if name in self.schedule else -1

    def slot_of(self, name: str) -> int:
        """Position of `name` within the repeating kernel."""
        return self.schedule[name][0] % self.ii if name in self.schedule else -1

    def num_stages(self) -> int:
