    def kernel_length(self) -> int:
        """Cycles spanned by the steady-state kernel."""
        return self.num_stages() * self.ii

    def prologue_length(self) -> int:
        """Cycles spent filling the pipeline before the kernel repeats."""
        if not self.schedule:
            return 0
        return (self.num_stages() - 1) * self.ii

    def epilogue_length(self) -> int:
        return self.prologue_length()

