            key = (cycle % self.ii, self.nodes[name].resource_type)
            usage[key] = usage.get(key, 0) + 1
        conflicts: Dict[str, int] = {}
        for (_, resource), count in usage.items():
            if count > 1:
                conflicts[resource] = conflicts.get(resource, 0) + count - 1
        return conflicts

    def _topological_sort(self) -> List[str]:
        visited: Set[str] = set()
        order: List[str] = []

        def visit(name: str) -> None:
            if name in visited:
                return
            visited.add(name)
            for pred in self.nodes[name].predecessors:
                if pred in self.nodes:
                    visit(pred)
