        order: List[str] = []

        def visit(name: str) -> None:
            if name in visited:
                return
            visited.add(name)
            for pred in self.nodes[name].predecessors:
                if pred in self.nodes:
                    visit(pred)
            order.append(name)

        for name in self.nodes:
            visit(name)
        return order

