class AXIStreamOp:
    """AXI Stream channel: framed beats carrying data, TID and TDEST."""
    name: str
    data_width: int = 64
    tid_width: int = 4
    tdest_width: int = 4
    buffer: List[Dict[str, int]] = field(default_factory=list)
    transfers_completed: int = 0

    def send(self, data: int, last: bool = False, tid: int = 0,
             tdest: int = 0) -> None:
        self.buffer.append({
            "data": data & ((1 << self.data_width) - 1),
            "last": 1 if last else 0,
            "tid": tid & ((1 << self.tid_width) - 1),
            "tdest": tdest & ((1 << self.tdest_width) - 1),
        })

