@dataclass
class MemoryBanking:
    """A memory split across banks so several addresses can be read at once."""
    name: str
    total_size: int = 1024
    num_banks: int = 4
    banking_type: str = "cyclic"
    banks: List[Dict[int, int]] = field(default_factory=list)

    def __post_init__(self) -> None:
        if not self.banks:
            self.banks = [{} for _ in range(self.num_banks)]

    def bank_index(self, address: int) -> int:
        """Bank that serves `address` under the configured banking scheme."""
        if self.banking_type == "cyclic":
            return address % self.num_banks
        if self.banking_type == "block":
            bank_size = self.total_size // self.num_banks
            if bank_size <= 0:
                return 0
            return min(address // bank_size, self.num_banks - 1)
        return 0

    def local_address(self, address: int) -> int:
        """Offset of `address` inside its bank."""
        if self.banking_type == "cyclic":
            return address // self.num_banks
        if self.banking_type == "block":
            bank_size = self.total_size // self.num_banks
            return address % bank_size if bank_size > 0 else 0
        return address

    def read(self, address: int) -> int:
        return self.banks[self.bank_index(address)].get(
            self.local_address(address), 0)

    def write(self, address: int, value: int) -> None:
        self.banks[self.bank_index(address)][self.local_address(address)] = value

    def can_parallel_access(self, addresses: List[int]) -> bool:
        """True when no two addresses share a bank."""
        seen: set = set()
        for address in addresses:
            bank = self.bank_index(address)
            if bank in seen:
                return False
            seen.add(bank)
        return True

    def conflict_count(self, addresses: List[int]) -> int:
        """Extra cycles the access pattern costs because banks collide."""
        counts: Dict[int, int] = {}
        for address in addresses:
            bank = self.bank_index(address)
            counts[bank] = counts.get(bank, 0) + 1
        return sum(count - 1 for count in counts.values() if count > 1)

    def burst_addresses(self, start: int, length: int) -> List[Tuple[int, int]]:
        """(bank, local address) pairs for a `length`-beat burst."""
        return [(self.bank_index(start + i), self.local_address(start + i))
                for i in range(length)]

    def occupancy(self) -> List[int]:
        return [len(bank) for bank in self.banks]

