from __future__ import annotations
from dataclasses import dataclass, field
from enum import Enum
from typing import Dict, List, Optional, Set


class NodeType(Enum):
    """Kinds of dataflow node, each with its own firing rule."""
    OPERATOR = "operator"
    FORK = "fork"
    JOIN = "join"
    MERGE = "merge"
    BRANCH = "branch"
    BUFFER = "buffer"
    SOURCE = "source"
    SINK = "sink"


@dataclass
class DataflowEdge:
    """A channel between two ports; it holds at most one token at a time."""
    source: str
    source_port: int
    target: str
    target_port: int
    data_width: int = 32
    has_token: bool = False
    token_value: int = 0
    buffer_slots: int = 0

    def transfer_token(self, value: int) -> None:
        self.token_value = value & ((1 << self.data_width) - 1)
        self.has_token = True

    def consume_token(self) -> Optional[int]:
        """Take the token, or ``None`` when the channel is empty."""
        if not self.has_token:
            return None
        value = self.token_value
        self.has_token = False
        self.token_value = 0
        return value

    def is_buffered(self) -> bool:
        return self.buffer_slots > 0


@dataclass
class DataflowNode:
    """A node with a firing rule determined by its :class:`NodeType`."""
    name: str
    node_type: NodeType = NodeType.OPERATOR
    latency: int = 1
    num_inputs: int = 1
    num_outputs: int = 1
    operation: str = "nop"
    fired_count: int = 0

    def can_fire(self, input_tokens: List[bool]) -> bool:
        """The firing rule: which inputs must carry a token."""
        if self.node_type == NodeType.MERGE:
            return any(input_tokens)
        if self.node_type == NodeType.JOIN:
            return all(input_tokens)
        if self.node_type == NodeType.FORK:
            return bool(input_tokens) and input_tokens[0]
        if self.node_type == NodeType.BRANCH:
            return len(input_tokens) >= 2 and input_tokens[0] and input_tokens[1]
        if self.node_type == NodeType.SOURCE:
            return True
        if self.node_type == NodeType.SINK:
            return any(input_tokens)
        return all(input_tokens[:self.num_inputs])

    def fire(self, input_values: List[int]) -> List[int]:
        """Consume `input_values` and produce one value per output port."""
        self.fired_count += 1
        if self.node_type == NodeType.FORK:
            value = input_values[0] if input_values else 0
            return [value] * self.num_outputs
        if self.node_type == NodeType.MERGE:
            for value in input_values:
                if value is not None:
                    return [value]
            return [0]
        if self.node_type == NodeType.JOIN:
            return [input_values[0]] if input_values else [0]
        if self.node_type == NodeType.BRANCH:
            data = input_values[0] if input_values else 0
            condition = input_values[1] if len(input_values) > 1 else 0
            return [data, 0] if condition else [0, data]
        if self.node_type == NodeType.OPERATOR:
            return [self._compute(input_values)]
        return [0]

    def _compute(self, input_values: List[int]) -> int:
        if len(input_values) >= 2:
            a, b = input_values[0], input_values[1]
            if self.operation == "add":
                return a + b
            if self.operation == "mul":
                return a * b
            if self.operation == "sub":
                return a - b
        return input_values[0] if input_values else 0

    def throughput_contribution(self) -> float:
        """Results per cycle this node alone can sustain."""
        if self.latency == 0:
            return float("inf")
        return 1.0 / self.latency


@dataclass
class DataflowGraph:
    """A graph of nodes and channels, executed by iterating the firing rules."""
    name: str
    nodes: Dict[str, DataflowNode] = field(default_factory=dict)
    edges: List[DataflowEdge] = field(default_factory=list)
    cycle_count: int = 0
    tokens_produced: int = 0
    tokens_consumed: int = 0

    # -- construction ----------------------------------------------------

    def add_node(self, node: DataflowNode) -> None:
        self.nodes[node.name] = node

    def add_edge(self, source: str, source_port: int,
                 target: str, target_port: int, width: int = 32) -> None:
        self.edges.append(DataflowEdge(
            source=source, source_port=source_port,
            target=target, target_port=target_port, data_width=width,
        ))

    def get_input_edges(self, node_name: str) -> List[DataflowEdge]:
        return [e for e in self.edges if e.target == node_name]

    def get_output_edges(self, node_name: str) -> List[DataflowEdge]:
        return [e for e in self.edges if e.source == node_name]

    # -- execution -------------------------------------------------------

    def step(self) -> int:
        """Fire every ready node once; returns how many fired."""
        fired: List[str] = []
        for name, node in self.nodes.items():
            input_edges = self.get_input_edges(name)
            input_tokens = [edge.has_token for edge in input_edges]
            if not input_edges and node.node_type == NodeType.SOURCE:
                # A source with no predecessor is always ready to emit.
                input_tokens = [True]
            if not node.can_fire(input_tokens):
                continue
            input_values: List[int] = []
            for edge in input_edges:
                value = edge.consume_token()
                input_values.append(value if value is not None else 0)
                self.tokens_consumed += 1
            outputs = node.fire(input_values)
            for index, edge in enumerate(self.get_output_edges(name)):
                if index < len(outputs):
                    edge.transfer_token(outputs[index])
                    self.tokens_produced += 1
            fired.append(name)
        self.cycle_count += 1
        return len(fired)

    def simulate(self, num_cycles: int) -> Dict[str, int]:
        """Run until `num_cycles` elapse or the graph stops firing."""
        total_fired = 0
        for _ in range(num_cycles):
            fired = self.step()
            total_fired += fired
            if fired == 0:
                break
        return {
            "cycles": self.cycle_count,
            "total_fired": total_fired,
            "tokens_produced": self.tokens_produced,
            "tokens_consumed": self.tokens_consumed,
        }

    def reset(self) -> None:
        for edge in self.edges:
            edge.has_token = False
            edge.token_value = 0
        for node in self.nodes.values():
            node.fired_count = 0
        self.cycle_count = 0
        self.tokens_produced = 0
        self.tokens_consumed = 0

    # -- analysis --------------------------------------------------------

    def throughput(self) -> float:
        if self.cycle_count == 0:
            return 0.0
        return self.tokens_produced / self.cycle_count

    def find_bottleneck(self) -> Optional[str]:
        """Operator with the lowest sustainable throughput."""
        slowest = float("inf")
        bottleneck: Optional[str] = None
        for name, node in self.nodes.items():
            if node.node_type != NodeType.OPERATOR:
                continue
            rate = node.throughput_contribution()
            if rate < slowest:
                slowest = rate
                bottleneck = name
        return bottleneck

    def insert_elastic_buffer(self, edge_index: int, slots: int = 1) -> None:
        if 0 <= edge_index < len(self.edges):
            self.edges[edge_index].buffer_slots = slots

    def node_count(self) -> int:
        return len(self.nodes)

    def edge_count(self) -> int:
        return len(self.edges)

    def firing_counts(self) -> Dict[str, int]:
        return {name: node.fired_count for name, node in self.nodes.items()}

    def dangling_nodes(self) -> Set[str]:
        """Nodes that are neither driven nor drive anything."""
        connected: Set[str] = set()
        for edge in self.edges:
            connected.add(edge.source)
            connected.add(edge.target)
        return set(self.nodes) - connected

    def verify(self) -> List[str]:
        """Structural problems: edges to unknown nodes, unconnected operators."""
        errors: List[str] = []
        for edge in self.edges:
            if edge.source not in self.nodes:
                errors.append(f"edge from unknown node {edge.source}")
            if edge.target not in self.nodes:
                errors.append(f"edge to unknown node {edge.target}")
        for name, node in self.nodes.items():
            if node.node_type == NodeType.OPERATOR:
                if len(self.get_input_edges(name)) < node.num_inputs:
                    errors.append(f"operator {name} is missing input channels")
        return errors

