"""Backend code generation: from scheduled K-CIRCT IR down to Verilog text.

:class:`CodeGenerator` is a line-oriented emitter -- the same shape as
:mod:`circt.emitter`, but driven by a schedule instead of a module body. The
three helper models around it cover what has to be decided before emission:
which signals need pipeline registers (:class:`RegisterAllocation`), where a
shared resource needs a multiplexer (:class:`MuxInsertion`), and whether the
clock tree can carry the resulting load (:class:`ClockTreeConstraints`).
"""
from __future__ import annotations
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional


@dataclass
class RegisterAllocation:
    """Pipeline registers, one entry per signal that crosses a stage boundary."""
    registers: Dict[str, int] = field(default_factory=dict)
    stage_assignments: Dict[str, int] = field(default_factory=dict)
    total_registers: int = 0

    def allocate(self, signal: str, stage: int, width: int = 1) -> int:
        """Reserve `width` register bits for `signal`; returns its register id."""
        reg_id = self.total_registers
        self.registers[signal] = reg_id
        self.stage_assignments[signal] = stage
        self.total_registers += width
        return reg_id

    def get_register(self, signal: str) -> Optional[int]:
        return self.registers.get(signal)

    def get_stage(self, signal: str) -> Optional[int]:
        return self.stage_assignments.get(signal)

    def registers_at_stage(self, stage: int) -> List[str]:
        return [signal for signal, at in self.stage_assignments.items()
                if at == stage]

    def total_register_bits(self) -> int:
        return self.total_registers


@dataclass
class MuxInsertion:
    """Multiplexers added where several producers share one consumer."""
    muxes: List[Dict[str, Any]] = field(default_factory=list)

    def insert_mux(self, output: str, inputs: List[str], select: str,
                   width: int = 32) -> int:
        mux_id = len(self.muxes)
        self.muxes.append({
            "id": mux_id, "output": output, "inputs": inputs,
            "select": select, "width": width,
        })
        return mux_id

    def mux_count(self) -> int:
        return len(self.muxes)

    def total_mux_inputs(self) -> int:
        return sum(len(mux["inputs"]) for mux in self.muxes)

    def select_width(self, mux_id: int) -> int:
        """Bits needed to select between one mux's inputs."""
        if not 0 <= mux_id < len(self.muxes):
            return 0
        num_inputs = len(self.muxes[mux_id]["inputs"])
        bits = 1
        while (1 << bits) < num_inputs:
            bits += 1
        return bits


@dataclass
class ClockTreeConstraints:
    """Timing-closure budget: target period, fanout limit and skew."""
    target_frequency_mhz: float = 100.0
    max_fanout: int = 32
    clock_regions: Dict[str, List[str]] = field(default_factory=dict)
    skew_budget_ps: float = 100.0

    def period_ns(self) -> float:
        if self.target_frequency_mhz <= 0:
            return 0.0
        return 1000.0 / self.target_frequency_mhz

    def assign_region(self, signal: str, region: str) -> None:
        self.clock_regions.setdefault(region, []).append(signal)

    def region_load(self, region: str) -> int:
        return len(self.clock_regions.get(region, []))

    def meets_fanout(self, region: str) -> bool:
        return self.region_load(region) <= self.max_fanout

    def num_buffers_needed(self, region: str) -> int:
        """Clock buffers required to drive a region within the fanout limit."""
        load = self.region_load(region)
        if load <= self.max_fanout:
            return 1
        return (load + self.max_fanout - 1) // self.max_fanout


class CodeGenerator:
    """Emits Verilog line by line; :meth:`get_output` returns the text."""

    def __init__(self) -> None:
        self.reg_alloc: RegisterAllocation = RegisterAllocation()
        self.mux_insert: MuxInsertion = MuxInsertion()
        self.clock_tree: ClockTreeConstraints = ClockTreeConstraints()
        self.output_lines: List[str] = []

    # -- declarations ----------------------------------------------------

    def emit_module_header(self, name: str, ports: List[Dict[str, Any]]) -> None:
        port_strs: List[str] = []
        for port in ports:
            direction = port.get("direction", "input")
            width = port.get("width", 1)
            pname = port.get("name", "sig")
            if width == 1:
                port_strs.append(f"  {direction} {pname}")
            else:
                port_strs.append(f"  {direction} [{width - 1}:0] {pname}")
        self.output_lines.append(f"module {name} (")
        self.output_lines.append(",\n".join(port_strs))
        self.output_lines.append(");")

    def emit_register(self, name: str, width: int, clock: str = "clk") -> None:
        if width == 1:
            self.output_lines.append(f"  reg {name};")
        else:
            self.output_lines.append(f"  reg [{width - 1}:0] {name};")

    def emit_wire(self, name: str, width: int) -> None:
        if width == 1:
            self.output_lines.append(f"  wire {name};")
        else:
            self.output_lines.append(f"  wire [{width - 1}:0] {name};")

    # -- behaviour -------------------------------------------------------

    def emit_assign(self, target: str, expression: str) -> None:
        self.output_lines.append(f"  assign {target} = {expression};")

    def emit_always_ff(self, clock: str, body: List[str],
                       reset: Optional[str] = None,
                       reset_body: Optional[List[str]] = None) -> None:
        if reset and reset_body:
            self.output_lines.append(
                f"  always_ff @(posedge {clock} or posedge {reset}) begin")
            self.output_lines.append(f"    if ({reset}) begin")
            for stmt in reset_body:
                self.output_lines.append(f"      {stmt}")
            self.output_lines.append("    end else begin")
            for stmt in body:
                self.output_lines.append(f"      {stmt}")
            self.output_lines.append("    end")
        else:
            self.output_lines.append(f"  always_ff @(posedge {clock}) begin")
            for stmt in body:
                self.output_lines.append(f"    {stmt}")
        self.output_lines.append("  end")

    def emit_mux(self, mux_id: int) -> None:
        """Emit one registered multiplexer as a chain of ternaries."""
        if not 0 <= mux_id < len(self.mux_insert.muxes):
            return
        mux = self.mux_insert.muxes[mux_id]
        expression = mux["inputs"][-1] if mux["inputs"] else "'0"
        for index in reversed(range(len(mux["inputs"]) - 1)):
            expression = (f"({mux['select']} == {index}) ? "
                          f"{mux['inputs'][index]} : {expression}")
        self.emit_assign(mux["output"], expression)

    def emit_module_footer(self) -> None:
        self.output_lines.append("endmodule")

    # -- output ----------------------------------------------------------

    def get_output(self) -> str:
        return "\n".join(self.output_lines)

    def line_count(self) -> int:
        return len(self.output_lines)

    def clear(self) -> None:
        self.output_lines.clear()

    def generate_pipeline(self, name: str, stages: List[Any],
                          width: int = 32) -> str:
        """Emit a skeleton module for a scheduled pipeline.

        `stages` is what :meth:`k_circt.hls_pipeline.HLSScheduler.build_pipeline_stages`
        returns: one entry per cycle, each naming the operations in it. Every
        operation gets a stage register, so the emitted module has the same
        latency as the schedule it came from.
        """
        self.clear()
        self.emit_module_header(name, [
            {"name": "clk", "direction": "input", "width": 1},
            {"name": "rst", "direction": "input", "width": 1},
            {"name": "in_valid", "direction": "input", "width": 1},
            {"name": "out_valid", "direction": "output", "width": 1},
        ])
        for stage in stages:
            for op_name in stage.operations:
                self.reg_alloc.allocate(op_name, stage.stage_id, width)
                self.emit_register(f"{op_name}_q", width)
        for stage in stages:
            for op_name in stage.operations:
                self.emit_always_ff("clk", [f"{op_name}_q <= {op_name}_d;"],
                                    reset="rst",
                                    reset_body=[f"{op_name}_q <= '0;"])
        self.emit_assign("out_valid", f"valid_stage_{max(len(stages) - 1, 0)}")
        self.emit_module_footer()
        return self.get_output()

