"""Symbol analysis: what a name means, and where it was bound.

The K-CIRCT layer resolves names before it evaluates anything, so evaluation can
assume every operand denotes something. A :class:`SymbolTable` is a scoped map
from name to :class:`Symbol`; :class:`SymbolResolver` fills one in from any of
the three IRs this project carries -- an :class:`mlir.ir.Operation` tree, a
:class:`circt.parser.Circuit` / :class:`circt.hw_dialect.HWModuleOp`, or a
:class:`k_circt.kernel_ir.KernelOp` -- and reports the references it could not
resolve.
"""
from __future__ import annotations
from dataclasses import dataclass, field
from enum import Enum
from typing import Any, Dict, Iterable, List, Optional, Set

from circt.hw_dialect import ConstantOp, HWModuleOp, InstanceOp, OutputOp, WireOp
from circt.parser import Circuit, op_mnemonic, op_operand_names
from circt.seq_dialect import is_stateful


class SymbolKind(Enum):
    """What a bound name denotes."""
    MODULE = "module"
    PORT_IN = "input_port"
    PORT_OUT = "output_port"
    WIRE = "wire"
    REGISTER = "register"
    CONSTANT = "constant"
    INSTANCE = "instance"
    OPERATION = "operation"
    KERNEL = "kernel"
    UNKNOWN = "unknown"


@dataclass
class Symbol:
    """One bound name."""
    name: str
    kind: SymbolKind = SymbolKind.UNKNOWN
    type_name: str = ""
    width: int = 0
    defining_op: Any = None
    uses: int = 0

    def is_value(self) -> bool:
        """True for names that carry a value at run time."""
        return self.kind not in (SymbolKind.MODULE, SymbolKind.KERNEL)

    def __repr__(self) -> str:
        suffix = f": {self.type_name}" if self.type_name else ""
        return f"Symbol({self.kind.value} {self.name}{suffix})"


class SymbolTable:
    """A lexical scope: names bound here, plus a link to the enclosing scope."""

    def __init__(self, scope: str = "", parent: Optional["SymbolTable"] = None) -> None:
        self.scope = scope
        self.parent = parent
        self.symbols: Dict[str, Symbol] = {}
        self.children: List["SymbolTable"] = []
        #: Names that were read without ever being bound.
        self.undefined: List[str] = []

    # -- binding ---------------------------------------------------------

    def define(self, symbol: Symbol) -> bool:
        """Bind `symbol`; ``False`` when the name is already bound here."""
        if symbol.name in self.symbols:
            return False
        self.symbols[symbol.name] = symbol
        return True

    def define_value(self, name: str, kind: SymbolKind, type_name: str = "",
                     width: int = 0, defining_op: Any = None) -> Symbol:
        symbol = Symbol(name=name, kind=kind, type_name=type_name,
                        width=width, defining_op=defining_op)
        self.define(symbol)
        return self.symbols[name]

    def push_scope(self, scope: str) -> "SymbolTable":
        child = SymbolTable(scope=scope, parent=self)
        self.children.append(child)
        return child

    # -- lookup ----------------------------------------------------------

    def lookup_local(self, name: str) -> Optional[Symbol]:
        return self.symbols.get(name)

    def lookup(self, name: str) -> Optional[Symbol]:
        """Find `name` here or in any enclosing scope."""
        scope: Optional[SymbolTable] = self
        while scope is not None:
            found = scope.symbols.get(name)
            if found is not None:
                return found
            scope = scope.parent
        return None

    def resolve(self, name: str) -> Optional[Symbol]:
        """Look `name` up and count the use; records it when unbound."""
        symbol = self.lookup(name)
        if symbol is None:
            if name not in self.undefined:
                self.undefined.append(name)
            return None
        symbol.uses += 1
        return symbol

    def resolve_all(self, names: Iterable[str]) -> List[Symbol]:
        return [s for s in (self.resolve(name) for name in names)
                if s is not None]

    # -- reporting -------------------------------------------------------

    def names(self) -> List[str]:
        return list(self.symbols)

    def of_kind(self, kind: SymbolKind) -> List[Symbol]:
        return [s for s in self.symbols.values() if s.kind == kind]

    def resolved(self) -> List[Symbol]:
        """Symbols that something actually referred to."""
        return [s for s in self.symbols.values() if s.uses > 0]

    def resolved_count(self) -> int:
        return len(self.resolved())

    def unused(self) -> List[Symbol]:
        return [s for s in self.symbols.values() if s.uses == 0]

    def all_symbols(self, recursive: bool = True) -> List[Symbol]:
        """Every symbol in this scope, and in nested scopes when asked."""
        found = list(self.symbols.values())
        if recursive:
            for child in self.children:
                found.extend(child.all_symbols(recursive=True))
        return found

    def all_undefined(self) -> List[str]:
        names = list(self.undefined)
        for child in self.children:
            for name in child.all_undefined():
                if name not in names:
                    names.append(name)
        return names

    def widths(self) -> Dict[str, int]:
        return {name: s.width for name, s in self.symbols.items() if s.width}

    def __len__(self) -> int:
        return len(self.symbols)

    def __contains__(self, name: str) -> bool:
        return self.lookup(name) is not None

    def __iter__(self):
        return iter(self.symbols.values())

    def __repr__(self) -> str:
        return f"SymbolTable({self.scope!r}, {len(self.symbols)} symbols)"


#: How each hardware operation's result should be classified.
_RESULT_KINDS = {
    "hw.constant": SymbolKind.CONSTANT,
    "hw.wire": SymbolKind.WIRE,
    "hw.instance": SymbolKind.INSTANCE,
    "seq.compreg": SymbolKind.REGISTER,
    "seq.compreg.ce": SymbolKind.REGISTER,
    "seq.firreg": SymbolKind.REGISTER,
}


class SymbolResolver:
    """Builds a :class:`SymbolTable` for a design and resolves its operands."""

    def __init__(self) -> None:
        self.table = SymbolTable(scope="<global>")
        #: One diagnostic string per problem found.
        self.diagnostics: List[str] = []

    # -- hardware IR -----------------------------------------------------

    def resolve_module(self, module: HWModuleOp,
                       into: Optional[SymbolTable] = None) -> SymbolTable:
        """Bind a module's ports and results, then resolve every operand."""
        scope = into or self.table.push_scope(module.name)
        for port in module.ports:
            kind = SymbolKind.PORT_OUT if port.is_output else SymbolKind.PORT_IN
            if not scope.define(Symbol(name=port.name, kind=kind,
                                       type_name=str(port.port_type),
                                       width=port.bit_width(),
                                       defining_op=module)):
                self.diagnostics.append(
                    f"@{module.name}: duplicate port {port.name}")
        widths = dict(module.attributes.get("signal_widths", {}))
        for op in module.body:
            for name in self._result_names(op):
                kind = _RESULT_KINDS.get(op_mnemonic(op), SymbolKind.OPERATION)
                if not scope.define(Symbol(
                        name=name, kind=kind,
                        type_name=f"i{widths.get(name, getattr(op, 'width', 0))}"
                        if widths.get(name, getattr(op, "width", 0)) else "",
                        width=widths.get(name, getattr(op, "width", 0)),
                        defining_op=op)):
                    self.diagnostics.append(
                        f"@{module.name}: {name} is defined more than once")
        for op in module.body:
            for name in op_operand_names(op):
                if scope.resolve(name) is None:
                    self.diagnostics.append(
                        f"@{module.name}: {op_mnemonic(op)} reads undefined %{name}")
            if isinstance(op, OutputOp):
                for name in op.operands:
                    scope.resolve(name)
        return scope

    def resolve_circuit(self, circuit: Circuit) -> SymbolTable:
        """Bind every module of `circuit`, then resolve each module body."""
        for module in circuit.modules:
            self.table.define(Symbol(name=module.name, kind=SymbolKind.MODULE,
                                     defining_op=module))
        for module in circuit.modules:
            self.resolve_module(module)
        for module in circuit.modules:
            for op in module.body:
                if isinstance(op, InstanceOp):
                    if self.table.resolve(op.module_name) is None:
                        self.diagnostics.append(
                            f"@{module.name}: instance {op.instance_name} "
                            f"references unknown module @{op.module_name}")
        return self.table

    # -- kernel IR -------------------------------------------------------

    def resolve_kernel(self, kernel: Any,
                       into: Optional[SymbolTable] = None) -> SymbolTable:
        """Bind a kernel's inputs and results, then resolve its operands."""
        scope = into or self.table.push_scope(kernel.name)
        scope.define(Symbol(name=kernel.name, kind=SymbolKind.KERNEL,
                            defining_op=kernel))
        for entry in kernel.inputs:
            scope.define(Symbol(name=entry["name"], kind=SymbolKind.PORT_IN,
                                width=entry.get("width", 0)))
        for op in kernel.operations:
            if op["result"]:
                if not scope.define(Symbol(name=op["result"],
                                           kind=SymbolKind.OPERATION,
                                           defining_op=op)):
                    self.diagnostics.append(
                        f"{kernel.name}: {op['result']} is defined more than once")
        for op in kernel.operations:
            for operand in op["operands"]:
                if scope.resolve(operand) is None:
                    self.diagnostics.append(
                        f"{kernel.name}: {op['name']} reads undefined {operand}")
        return scope

    # -- core MLIR -------------------------------------------------------

    def resolve_mlir(self, module: Any) -> SymbolTable:
        """Bind the symbol-table operations of an :mod:`mlir` module."""
        def visit(op: Any) -> None:
            attr = op.get_attr("sym_name")
            if attr is not None:
                name = str(attr).strip('"')
                if not self.table.define(Symbol(name=name,
                                                kind=SymbolKind.MODULE,
                                                defining_op=op)):
                    self.diagnostics.append(f"duplicate symbol @{name}")

        module.walk(visit)
        return self.table

    # -- helpers ---------------------------------------------------------

    def _result_names(self, op: Any) -> List[str]:
        if isinstance(op, InstanceOp):
            return list(op.outputs)
        if isinstance(op, OutputOp):
            return []
        name = getattr(op, "result_name", "")
        if not name and is_stateful(op):
            name = getattr(op, "name", "")
        return [name] if name else []

    def undefined_references(self) -> List[str]:
        return self.table.all_undefined()

    def symbol_count(self) -> int:
        return len(self.table.all_symbols())


def analyze_symbols(design: Any) -> SymbolTable:
    """Resolve `design`, dispatching on which IR it is expressed in."""
    resolver = SymbolResolver()
    if isinstance(design, Circuit):
        resolver.resolve_circuit(design)
        return resolver.table
    if isinstance(design, HWModuleOp):
        return resolver.resolve_module(design)
    if hasattr(design, "operations") and hasattr(design, "total_operations"):
        return resolver.resolve_kernel(design)
    resolver.resolve_mlir(design)
    return resolver.table

