        if isinstance(op, InstanceOp):
            return list(op.outputs)
        if isinstance(op, OutputOp):
            return []
        name = getattr(op, "result_name", "")
        if not name and is_stateful(op):
            name = getattr(op, "name", "")
        return [name] if name else []

    def undefined_references(self) -> List[str]:
        return self.table.all_undefined()

    def symbol_count(self) -> int:
        return len(self.table.all_symbols())


def analyze_symbols(design: Any) -> SymbolTable:
    """Resolve `design`, dispatching on which IR it is expressed in."""
    resolver = SymbolResolver()
    if isinstance(design, Circuit):
        resolver.resolve_circuit(design)
        return resolver.table
    if isinstance(design, HWModuleOp):
        return resolver.resolve_module(design)
    if hasattr(design, "operations") and hasattr(design, "total_operations"):
        return resolver.resolve_kernel(design)
    resolver.resolve_mlir(design)
