        return "?"

    def __repr__(self) -> str:
        return f"{type(self).__name__}({self})"


@dataclass(frozen=True)
class KIntType(KType):
    """An integer of `width` bits, printed the MLIR way: ``i32``."""
    width: int

    def bit_width(self) -> int:
        return self.width

    def mask(self) -> int:
        return (1 << self.width) - 1

    def __str__(self) -> str:
        return f"i{self.width}"


@dataclass(frozen=True)
class KClockType(KType):
    """The clock type, which carries a value but never arithmetic."""

    def bit_width(self) -> int:
        return 1

    def __str__(self) -> str:
        return "!seq.clock"


@dataclass(frozen=True)
class KResetType(KType):
    """A reset line: one bit, but distinguished from a plain ``i1``."""

    def bit_width(self) -> int:
        return 1

    def __str__(self) -> str:
        return "!seq.reset"


@dataclass(frozen=True)
class KArrayType(KType):
