@dataclass(frozen=True)
class KTupleType(KType):
    """Several values travelling together, e.g. a module's results."""
    element_types: Tuple[KType, ...] = ()

    def bit_width(self) -> int:
        return sum(t.bit_width() for t in self.element_types)

    def __str__(self) -> str:
