        return self.bindings.get(name, UNKNOWN)

    def width_of(self, name: str) -> int:
        return self.lookup(name).bit_width()

    def widths(self) -> Dict[str, int]:
        return {name: t.bit_width() for name, t in self.bindings.items()
                if t.is_known()}

    def known(self) -> Dict[str, KType]:
        return {name: t for name, t in self.bindings.items() if t.is_known()}

    def unknown_names(self) -> List[str]:
        return [name for name, t in self.bindings.items() if not t.is_known()]

    def __contains__(self, name: str) -> bool:
