    """Derives result types and reports operations whose operands disagree."""

    def __init__(self, env: Optional[TypeEnvironment] = None) -> None:
        self.env = env or TypeEnvironment()
        self.diagnostics: List[str] = []

    # -- inference -------------------------------------------------------

    def infer(self, op: Any) -> KType:
