            return KIntType(op.width)
        if isinstance(op, ReplicateOp):
            return KIntType(op.input_width * op.count)
        if isinstance(op, MuxOp):
            # The condition is i1; the result follows the two arms.
            return self._first_known(op.operands[1:]) or KIntType(op.width)
        if isinstance(op, WireOp):
            return self._first_known(op_operand_names(op)) or KIntType(
