        """Diagnostics for one operation; also binds its result type."""
        problems: List[str] = []
        mnemonic = op_mnemonic(op)
        if isinstance(op, ICmpOp):
            widths = {self.env.width_of(name) for name in op.operands}
            widths.discard(0)
            if len(widths) > 1:
                problems.append(
                    f"{mnemonic}: comparing operands of different widths {sorted(widths)}")
        elif isinstance(op, MuxOp) and len(op.operands) == 3:
            condition = self.env.width_of(op.operands[0])
            if condition not in (0, 1):
                problems.append(
                    f"{mnemonic}: condition must be i1, got i{condition}")
            arms = {self.env.width_of(name) for name in op.operands[1:]}
            arms.discard(0)
            if len(arms) > 1:
                problems.append(
                    f"{mnemonic}: arms have different widths {sorted(arms)}")
        elif mnemonic.startswith("comb.") and not isinstance(
                op, (ConcatOp, ExtractOp, ReplicateOp)):
            widths = {self.env.width_of(name)
                      for name in getattr(op, "operands", [])}
            widths.discard(0)
            if len(widths) > 1:
                problems.append(
                    f"{mnemonic}: operands have different widths {sorted(widths)}")
        result = getattr(op, "result_name", "")
        inferred = self.infer(op)
        if result and inferred.is_known():
            self.env.bind(result, inferred)
        self.diagnostics.extend(problems)
        return problems

    def check_module(self, module: HWModuleOp) -> List[str]:
        """Type-check a whole module, seeding the environment from its ports."""
        self.env = TypeEnvironment.from_module(module)
        self.diagnostics = []
        for op in module.body:
            self.check(op)
        terminator = module.terminator
        if terminator is not None:
            for port, name in zip(module.output_ports, terminator.operands):
                declared = type_of(port.port_type).bit_width()
                actual = self.env.width_of(name)
                if declared and actual and declared != actual:
                    self.diagnostics.append(
                        f"@{module.name}: output {port.name} is i{declared} "
                        f"but {name} is i{actual}")
        return list(self.diagnostics)

    def resolve_module_types(self, module: HWModuleOp) -> Dict[str, str]:
        """Textual type of every named value in `module`."""
        self.check_module(module)
        return {name: str(t) for name, t in self.env.bindings.items()}

    # -- helpers ---------------------------------------------------------

    def _first_known(self, names: List[str]) -> Optional[KType]:
        for name in names:
            found = self.env.lookup(name)
            if found.is_known():
                return found
        return None

    def _operand_width(self, op: Any, index: int) -> int:
        widths = getattr(op, "operand_widths", None)
        if widths and index < len(widths):
            return widths[index]
        return self.env.width_of(op.operands[index])


class KernelTypeAnalysis:
    """Type inference for the kernel IR, where widths come from the interface.

    Kernel operations carry no types of their own, so every result is given the
    kernel's data width unless a comparison narrows it to ``i1``.
    """

    #: Operations whose result is a single bit rather than a full word.
    PREDICATE_OPS = frozenset({"cmp", "icmp", "eq", "ne", "lt", "gt"})

    def __init__(self, data_width: int = 32) -> None:
        self.data_width = data_width
        self.env = TypeEnvironment()
        self.diagnostics: List[str] = []

    def analyze(self, kernel: Any) -> TypeEnvironment:
        """Bind types for a kernel's inputs and every operation result."""
        self.env = TypeEnvironment()
        self.diagnostics = []
        for entry in kernel.inputs:
            self.env.bind(entry["name"],
                          KIntType(entry.get("width", self.data_width)))
        for op in kernel.operations:
            for operand in op["operands"]:
                if operand not in self.env:
                    # An operand nothing defines still has the interface width.
                    self.env.bind(operand, KIntType(self.data_width))
            self.env.bind(op["result"], self.result_type(op))
        for entry in kernel.outputs:
            declared = entry.get("width", self.data_width)
            actual = self.env.width_of(entry["name"])
            if actual and actual != declared:
                self.diagnostics.append(
                    f"{kernel.name}: output {entry['name']} is i{actual} "
                    f"but declared i{declared}")
        return self.env

    def result_type(self, op: Dict[str, Any]) -> KType:
        if op["op_type"] in self.PREDICATE_OPS:
            return KIntType(1)
        return KIntType(self.data_width)

    def resolve(self, kernel: Any, name: str = "") -> str:
        """Textual type of `name`, or of the kernel's last result."""
        env = self.analyze(kernel)
        if name:
            return str(env.lookup(name))
        if kernel.operations:
            return str(env.lookup(kernel.operations[-1]["result"]))
        return str(UNKNOWN)


def analyze_types(module: HWModuleOp) -> TypeEnvironment:
    """Convenience wrapper: type-check `module` and return its environment."""
    checker = TypeChecker()
    checker.check_module(module)
    return checker.env

