input.content:
"""Stateful circuit execution: the configuration the semantic rules rewrite.

A K configuration is a bag of labelled cells. The one used here has five:

``<k>``
    operations still waiting to be evaluated this cycle;
``<env>``
    values that have settled so far, keyed by signal name;
``<regs>``
    the latched register state, which is the only thing that survives a cycle;
``<inputs>``
    the stimulus driving the module's input ports;
``<cycle>``
    how many clock edges have been taken.

:class:`StatefulExecutor` rewrites that configuration with the rules in
:mod:`k_circt.semantics`: the settle phase drains ``<k>`` into ``<env>``, and the
edge phase moves ``<env>`` into ``<regs>``. Every rewrite is recorded, which is
what :class:`k_circt.kimulator.Kimulator` turns into a trace.
"""
from __future__ import annotations
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional

from circt.comb_dialect import CombOp
from circt.hw_dialect import ConstantOp, HWModuleOp, InstanceOp, OutputOp, WireOp
from circt.parser import op_mnemonic
from circt.seq_dialect import is_stateful

from .semantics import CIRCUIT_RULES, EDGE_RULES, RuleApplication, RuleSet


class ExecutionError(RuntimeError):
    """Raised when a configuration cannot be reduced any further."""


@dataclass
class Cell:
    """One labelled cell of a configuration."""
    name: str
    value: Any

    def render(self) -> str:
        return f"<{self.name}> {self.value} </{self.name}>"

    def __str__(self) -> str:
        return self.render()


@dataclass
class Configuration:
    """The cells the semantics rewrites, as one value."""
    k: List[Any] = field(default_factory=list)
    env: Dict[str, int] = field(default_factory=dict)
    regs: Dict[str, int] = field(default_factory=dict)
    inputs: Dict[str, int] = field(default_factory=dict)
    cycle: int = 0
    phase: str = "settle"

    #: Cell order used when rendering, matching the docstring above.
    CELL_ORDER = ("k", "env", "regs", "inputs", "cycle")

    def cells(self) -> List[Cell]:
        return [Cell(name, getattr(self, name)) for name in self.CELL_ORDER]

    def cell(self, name: str) -> Any:
        if name not in self.CELL_ORDER:
            raise KeyError(f"no cell <{name}> in this configuration")
        return getattr(self, name)

    def is_settled(self) -> bool:
        """True once ``<k>`` is empty, i.e. nothing is left to evaluate."""
        return not self.k

    def snapshot(self) -> Dict[str, Any]:
        return {
            "k": list(self.k), "env": dict(self.env), "regs": dict(self.regs),
            "inputs": dict(self.inputs), "cycle": self.cycle, "phase": self.phase,
        }

    def restore(self, snapshot: Dict[str, Any]) -> None:
        self.k = list(snapshot["k"])
        self.env = dict(snapshot["env"])
        self.regs = dict(snapshot["regs"])
        self.inputs = dict(snapshot["inputs"])
        self.cycle = snapshot["cycle"]
        self.phase = snapshot["phase"]

    def render(self) -> str:
        """The configuration in the notation a K definition would print."""
        pending = " ~> ".join(op_mnemonic(op) for op in self.k) or "."
        env = ", ".join(f"{k} |-> {v}" for k, v in sorted(self.env.items())) or "."
        regs = ", ".join(f"{k} |-> {v}" for k, v in sorted(self.regs.items())) or "."
        inputs = ", ".join(f"{k} |-> {v}"
                           for k, v in sorted(self.inputs.items())) or "."
        return "\n".join([
            "<config>",
            f"  <k> {pending} </k>",
            f"  <env> {env} </env>",
            f"  <regs> {regs} </regs>",
            f"  <inputs> {inputs} </inputs>",
            f"  <cycle> {self.cycle} </cycle>",
            "</config>",
        ])

    def __str__(self) -> str:
        return self.render()


class CircuitState:
    """The register file of a module: the state that survives a clock edge."""

    def __init__(self, module: HWModuleOp) -> None:
        self.registers: Dict[str, Any] = {}
        for op in module.body:
            if is_stateful(op):
                name = getattr(op, "result_name", "") or getattr(op, "name", "")
                if name:
                    self.registers[name] = op

    def values(self) -> Dict[str, int]:
        return {name: op.get_value() for name, op in self.registers.items()}

    def get(self, name: str) -> int:
        op = self.registers.get(name)
        return op.get_value() if op is not None else 0

    def set(self, name: str, value: int) -> None:
        op = self.registers.get(name)
        if op is not None:
            op.current_value = value & ((1 << op.width) - 1)

    def latch(self, next_values: Dict[str, int]) -> None:
        """Commit every register at once, so they update in parallel."""
        for name, value in next_values.items():
            self.set(name, value)

    def reset(self) -> None:
        for op in self.registers.values():
            op.current_value = 0

    def snapshot(self) -> Dict[str, int]:
        return self.values()

    def restore(self, snapshot: Dict[str, int]) -> None:
        self.latch(snapshot)

    def __len__(self) -> int:
        return len(self.registers)

    def __contains__(self, name: str) -> bool:
        return name in self.registers


class StatefulExecutor:
    """Evaluates a module by rewriting a :class:`Configuration` with rules."""

    #: Safety valve for the settle loop, which must reach a fixed point.
    MAX_SETTLE_ITERATIONS = 256

    def __init__(self, module: HWModuleOp, circuit: Optional[Any] = None,
                 rules: RuleSet = CIRCUIT_RULES,
                 edge_rules: RuleSet = EDGE_RULES,
                 record: bool = True) -> None:
        self.module = module
        self.circuit = circuit
        self.rules = rules
        self.edge_rules = edge_rules
        self.record = record
        self.state = CircuitState(module)
        self.signal_widths: Dict[str, int] = dict(
            module.attributes.get("signal_widths", {}))
        self.config = Configuration(
            inputs={port.name: 0 for port in module.input_ports})
        #: Every rule application, in the order the rules fired.
        self.applications: List[RuleApplication] = []
        self.instances: Dict[str, "StatefulExecutor"] = {}
        self._combinational: List[Any] = []
        self._collect()
        self.settle()

    # -- setup -----------------------------------------------------------

    def _collect(self) -> None:
        for op in self.module.body:
            if is_stateful(op) or isinstance(op, OutputOp):
                continue
            if isinstance(op, InstanceOp):
                self._bind_instance(op)
                continue
            if isinstance(op, (ConstantOp, CombOp, WireOp)):
                self._combinational.append(op)

    def _bind_instance(self, op: InstanceOp) -> None:
        if self.circuit is None:
            return
        submodule = self.circuit.get_module(op.module_name)
        if submodule is not None:
            self.instances[op.instance_name] = StatefulExecutor(
                submodule, circuit=self.circuit, rules=self.rules,
                edge_rules=self.edge_rules, record=False)

    # -- stimulus --------------------------------------------------------

    def set_input(self, name: str, value: int) -> None:
        width = self.signal_widths.get(name, 32)
        self.config.inputs[name] = value & ((1 << width) - 1)

    def set_inputs(self, values: Dict[str, int]) -> None:
        for name, value in values.items():
            self.set_input(name, value)

    # -- the settle phase ------------------------------------------------

    def settle(self, inputs: Optional[Dict[str, int]] = None) -> Configuration:
        """Drain ``<k>`` into ``<env>``, applying one rule per operation."""
        if inputs:
            self.set_inputs(inputs)
        self.config.phase = "settle"
        self.config.regs = self.state.values()
        self.config.env = dict(self.config.inputs)
        # A register reads as its latched value, which is what breaks the
        # apparent cycle between %reg and %next in a counter.
        for name, op in self.state.registers.items():
            self._fire(self.rules, op, name_override=name)
        self.config.k = list(self._combinational)
        for _ in range(self.MAX_SETTLE_ITERATIONS):
            if self.config.is_settled():
                break
            blocked: List[Any] = []
            progressed = False
            for op in self.config.k:
                rule = self.rules.match(op, self.config.env)
                if rule is None or not rule.is_ready(op, self.config.env):
                    blocked.append(op)
                    continue
                self._fire(self.rules, op)
                progressed = True
            self.config.k = blocked
            if not progressed:
                break
        if self.config.k:
            stuck = ", ".join(
                getattr(op, "result_name", op_mnemonic(op))
                for op in self.config.k)
            raise ExecutionError(
                f"@{self.module.name} does not settle: {stuck}")
        self._settle_instances()
        return self.config

    def _fire(self, rules: RuleSet, op: Any,
              name_override: str = "") -> Optional[RuleApplication]:
        application = rules.apply(op, self.config.env, self.config.cycle)
        if application is None:
            return None
        target = name_override or application.target
        if application.result is not None and target:
            self.config.env[target] = application.result
        if self.record:
            self.applications.append(application)
        return application

    def _settle_instances(self) -> None:
        for op in self.module.body:
            if not isinstance(op, InstanceOp):
                continue
            instance = self.instances.get(op.instance_name)
            if instance is None:
                continue
            instance.set_inputs({port: self.config.env.get(signal, 0)
                                 for port, signal in op.inputs.items()})
            instance.settle()
            for index, name in enumerate(op.outputs):
                ports = instance.module.output_ports
                if index < len(ports):
                    self.config.env[name] = instance.outputs()[ports[index].name]

    # -- the edge phase --------------------------------------------------

    def latch(self) -> Dict[str, int]:
        """Apply the edge rules, then commit every register at once."""
        self.config.phase = "edge"
        next_values: Dict[str, int] = {}
        for name, op in self.state.registers.items():
            application = self.edge_rules.apply(op, self.config.env,
                                                self.config.cycle)
            if application is None:
                next_values[name] = op.get_value()
                continue
            if self.record:
                self.applications.append(application)
            next_values[name] = (application.result
                                 if application.result is not None
                                 else op.get_value())
        self.state.latch(next_values)
        for instance in self.instances.values():
            instance.latch()
        return next_values

    def step(self, inputs: Optional[Dict[str, int]] = None) -> Configuration:
        """One clock cycle: settle, latch, advance time, settle again."""
        self.settle(inputs)
        self.latch()
        self.config.cycle += 1
        return self.settle()

    def run(self, cycles: int,
            inputs: Optional[Dict[str, int]] = None) -> List[Configuration]:
        return [self.step(inputs) for _ in range(cycles)]

    def evaluate(self, inputs: Dict[str, int]) -> Dict[str, int]:
        """Drive a combinational design and return its output ports."""
        self.settle(inputs)
        return self.outputs()

    # -- observation -----------------------------------------------------

    def outputs(self) -> Dict[str, int]:
        terminator = self.module.terminator
        if terminator is None:
            return {}
        result: Dict[str, int] = {}
        for index, port in enumerate(self.module.output_ports):
            if index < len(terminator.operands):
                name = terminator.operands[index]
                result[port.name] = self.config.env.get(name, 0)
        return result

    def get_signal(self, name: str) -> int:
        return self.config.env.get(name, 0)

    def register_values(self) -> Dict[str, int]:
        return self.state.values()

    def reset(self) -> None:
        """Clear state and rule history, then re-settle from zero."""
        self.state.reset()
        self.applications = []
        self.config.cycle = 0
        for instance in self.instances.values():
            instance.reset()
        self.settle()

    def rule_counts(self) -> Dict[str, int]:
        counts: Dict[str, int] = {}
        for application in self.applications:
            counts[application.rule] = counts.get(application.rule, 0) + 1
        return counts

    def __repr__(self) -> str:
        return (f"StatefulExecutor(@{self.module.name}, "
                f"cycle={self.config.cycle}, regs={len(self.state)})")

