input.content:
"""Kimulator: the trace engine that evaluates circuits through semantic rules.

The Kimulator is the observable half of the semantic layer. It owns a
:class:`k_circt.state.StatefulExecutor`, so evaluation happens by rewriting a
configuration with the rules in :mod:`k_circt.semantics`, and it collects every
rewrite into a :class:`Trace`. That trace is the point: a value is not just
computed, it comes with the sequence of rules that produced it, which can be
rendered, filtered by rule or by cycle, and compared against the cycle-accurate
:class:`circt.simulator.CircuitSimulator` for the same design.
"""
from __future__ import annotations
from dataclasses import dataclass, field
from typing import Any, Dict, Iterator, List, Optional

from circt.hw_dialect import HWModuleOp
from circt.parser import Circuit, parse_circuit_file

from .semantics import CIRCUIT_RULES, EDGE_RULES, RuleApplication, RuleSet
from .state import Configuration, StatefulExecutor
from .symbols import SymbolResolver, SymbolTable
from .types import TypeChecker, TypeEnvironment


@dataclass
class Trace:
    """The sequence of rule applications an evaluation performed."""
    entries: List[RuleApplication] = field(default_factory=list)

    def append(self, entry: RuleApplication) -> None:
        self.entries.append(entry)

    def extend(self, entries: List[RuleApplication]) -> None:
        self.entries.extend(entries)

    def by_rule(self, rule: str) -> List[RuleApplication]:
        return [e for e in self.entries if e.rule == rule]

    def by_cycle(self, cycle: int) -> List[RuleApplication]:
        return [e for e in self.entries if e.cycle == cycle]

    def by_phase(self, phase: str) -> List[RuleApplication]:
        return [e for e in self.entries if e.phase == phase]

    def rule_counts(self) -> Dict[str, int]:
        counts: Dict[str, int] = {}
        for entry in self.entries:
            counts[entry.rule] = counts.get(entry.rule, 0) + 1
        return counts

    def values_of(self, signal: str) -> List[int]:
        """Every value a signal took, in the order the rules produced it."""
        return [e.result for e in self.entries
                if e.target == signal and e.result is not None]

    def cycles(self) -> int:
        """Number of distinct cycles the trace covers."""
        return len({e.cycle for e in self.entries})

    def render(self, limit: int = 0) -> str:
        entries = self.entries[:limit] if limit else self.entries
        return "\n".join(entry.render() for entry in entries)

    def __len__(self) -> int:
        return len(self.entries)

    def __iter__(self) -> Iterator[RuleApplication]:
        return iter(self.entries)

    def __getitem__(self, index: int) -> RuleApplication:
        return self.entries[index]

    def __repr__(self) -> str:
        return f"Trace({len(self.entries)} applications)"


class Kimulator:
    """Rule-driven evaluator for one `hw.module`, with a full trace."""

    def __init__(self, module: HWModuleOp, circuit: Optional[Circuit] = None,
                 rules: RuleSet = CIRCUIT_RULES,
                 edge_rules: RuleSet = EDGE_RULES) -> None:
        self.module = module
        self.circuit = circuit
        self.executor = StatefulExecutor(module, circuit=circuit, rules=rules,
                                         edge_rules=edge_rules)
        #: Names resolved before evaluation, so every operand denotes something.
        self.symbols: SymbolTable = SymbolResolver().resolve_module(module)
        self._checker = TypeChecker()
        self._checker.check_module(module)
        self.trace = Trace()
        self._sync_trace()

    # -- construction helpers --------------------------------------------

    @classmethod
    def from_circuit(cls, circuit: Circuit,
                     module_name: str = "") -> "Kimulator":
        """Build a Kimulator for one module of an already parsed circuit."""
        module = (circuit.get_module(module_name) if module_name
                  else circuit.top_module())
        if module is None:
            raise KeyError(f"no module @{module_name} in circuit")
        return cls(module, circuit=circuit)

    @classmethod
    def from_file(cls, path: str, module_name: str = "") -> "Kimulator":
        """Parse a CIRCT source file and evaluate one of its modules."""
        return cls.from_circuit(parse_circuit_file(path), module_name)

    # -- analysis --------------------------------------------------------

    @property
    def types(self) -> TypeEnvironment:
        """Types inferred for every named value in the module."""
        return self._checker.env

    def type_of(self, signal: str) -> str:
        return str(self.types.lookup(signal))

    def diagnostics(self) -> List[str]:
        """Everything symbol and type analysis found wrong with the module."""
        resolver = SymbolResolver()
        resolver.resolve_module(self.module)
        return resolver.diagnostics + list(self._checker.diagnostics)

    def rules_used(self) -> Dict[str, int]:
        return self.trace.rule_counts()

    # -- evaluation ------------------------------------------------------

    def evaluate(self, inputs: Optional[Dict[str, int]] = None) -> Dict[str, int]:
        """Settle the module under `inputs` and return its output ports."""
        self.executor.settle(inputs or {})
        self._sync_trace()
        return self.executor.outputs()

    def step(self, inputs: Optional[Dict[str, int]] = None) -> Configuration:
        """Take one clock edge, recording every rule that fired."""
        config = self.executor.step(inputs)
        self._sync_trace()
        return config

    def run(self, cycles: int,
            inputs: Optional[Dict[str, int]] = None) -> Trace:
        """Clock the design `cycles` times and return the accumulated trace."""
        for _ in range(cycles):
            self.step(inputs)
        return self.trace

    def reset(self) -> None:
        self.executor.reset()
        self.trace = Trace()
        self._sync_trace()

    # -- observation -----------------------------------------------------

    def outputs(self) -> Dict[str, int]:
        return self.executor.outputs()

    def get_output(self, name: str = "") -> int:
        outputs = self.outputs()
        if not name:
            return next(iter(outputs.values()), 0)
        return outputs.get(name, 0)

    def get_signal(self, name: str) -> int:
        return self.executor.get_signal(name)

    def register_values(self) -> Dict[str, int]:
        return self.executor.register_values()

    @property
    def configuration(self) -> Configuration:
        return self.executor.config

    @property
    def cycle(self) -> int:
        return self.executor.config.cycle

    def trace_length(self) -> int:
        return len(self.trace)

    def render_trace(self, limit: int = 0) -> str:
        return self.trace.render(limit)

    def _sync_trace(self) -> None:
        """Move whatever the executor recorded into the trace."""
        new = self.executor.applications[len(self.trace):]
