def resolve_module(self, module: HWModuleOp,
                   into: Optional[SymbolTable] = None) -> SymbolTable:
    """Bind a module's ports and results, then resolve every operand."""
    scope = into or self.table.push_scope(module.name)
    for port in module.ports:
        kind = SymbolKind.PORT_OUT if port.is_output else SymbolKind.PORT_IN
        if not scope.define(Symbol(name=port.name, kind=kind,
                                   type_name=str(port.port_type),
                                   width=port.bit_width(),
                                   defining_op=module)):
            self.diagnostics.append(
                f"@{module.name}: duplicate port {port.name}")
    widths = dict(module.attributes.get("signal_widths", {}))
    for op in module.body:
        for name in self._result_names(op):
            kind = _RESULT_KINDS.get(op_mnemonic(op), SymbolKind.OPERATION)
            if not scope.define(Symbol(
                    name=name, kind=kind,
                    type_name=f"i{widths.get(name, getattr(op, 'width', 0))}"
                    if widths.get(name, getattr(op, "width", 0)) else "",
                    width=widths.get(name, getattr(op, "width", 0)),
                    defining_op=op)):
                self.diagnostics.append(
                    f"@{module.name}: {name} is defined more than once")
    for op in module.body:
        for name in op_operand_names(op):
            if scope.resolve(name) is None:
                self.diagnostics.append(
                    f"@{module.name}: {op_mnemonic(op)} reads undefined %{name}")
        if isinstance(op, OutputOp):
            for name in op.operands:
                scope.resolve(name)
    return scope

